files.content:
.root {
  --vt-surface: #FFFFFF;
  --vt-surface-2: #F9F9F9;
  --vt-surface-deep: #000000;
  --vt-ink: #000000;
  --vt-ink-soft: #717275;
  --vt-on-deep: #FFFFFF;
  --vt-accent: #247cff;
  --vt-on-accent: #FFFFFF;
  --vt-accent-ink: #1a4d8f;
  --vt-accent-on-deep: #5a9ef5;
  --vt-line: #eaeaea;

  background: var(--vt-surface);
  color: var(--vt-ink);
  font-family: 'Open Sans', sans-serif;
  padding-top: 94px;
}

.root a:focus-visible {
  outline: 2px solid var(--vt-accent);
  outline-offset: 2px;
}

.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: var(--vt-surface);
  box-shadow: 0 0 1rem rgba(0, 0, 0, 0.1);
}

.navIn {
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 15px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  height: 94px;
  box-sizing: border-box;
}

.logo {
  text-decoration: none;
  color: var(--vt-accent-ink);
  display: flex;
  align-items: center;
}

.brand {
  margin: 0;
}

.navLinks {
  display: flex;
  gap: 1.5rem;
}

.navLinks a {
  text-decoration: none;
  color: var(--vt-ink-soft);
  font-weight: 600;
  font-size: 16px;
  padding: 15px 0;
  transition: color 0.3s;
}

.navLinks a:hover {
  color: var(--vt-ink);
}

.hero {
  position: relative;
}

.heroImageWrap {
  height: 580px;
  overflow: hidden;
}

.heroImage {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.heroText {
  position: absolute;
  bottom: 0;
  right: 0;
  background: var(--vt-surface);
  padding: 2rem 2.5rem;
  width: 50%;
  z-index: 2;
  box-sizing: border-box;
}

.heroTitle {
  font-size: 48px;
  color: var(--vt-ink);
  font-weight: 700;
  margin-bottom: 0.5rem;
  line-height: 1.2;
}

.animatedInfo {
  display: inline-block;
  vertical-align: top;
  min-width: 250px;
  position: relative;
}

.animatedItem {
  display: block;
  opacity: 0;
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  animation: bottomToTop 6s linear infinite;
  color: var(--vt-accent-ink);
}

@keyframes bottomToTop {
  0% { opacity: 0; transform: translateY(5px); }
  5% { opacity: 0; transform: translateY(5px); }
  10% { opacity: 1; transform: translateY(0); }
  25% { opacity: 1; transform: translateY(0); }
  30% { opacity: 0; transform: translateY(5px); }
  80% { opacity: 0; }
  100% { opacity: 0; }
}

.heroLead {
  color: var(--vt-ink-soft);
  font-size: 18px;
  font-weight: 300;
  margin-bottom: 1.5rem;
}

.heroLinks {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
}

.customLink {
  display: inline-block;
  border: 1px solid var(--vt-line);
  color: var(--vt-accent-ink);
  font-weight: 600;
  line-height: 40px;
  padding: 0 30px;
  text-decoration: none;
  text-transform: uppercase;
  position: relative;
  overflow: hidden;
}

.customLink::before {
  content: attr(data-hover);
  background-color: var(--vt-line);
  color: var(--vt-accent-ink);
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  bottom: 0;
  text-align: center;
  transition: top 0.3s;
}

.customLink:hover::before {
  top: 0;
}

.contactPhone {
  font-weight: 600;
  color: var(--vt-ink);
  margin: 0;
}

.sectionPadding {
  padding-top: 7rem;
  padding-bottom: 7rem;
}

.container {
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 15px;
  box-sizing: border-box;
}

.aboutRow {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
}

.aboutText {
  flex: 1 1 60%;
  padding-right: 2rem;
  box-sizing: border-box;
}

.aboutTitle {
  color: var(--vt-ink);
  font-size: 36px;
  margin-bottom: 1rem;
}

.aboutImageWrap {
  flex: 1 1 40%;
}

.aboutImage {
  width: 100%;
  height: auto;
  display: block;
}

.gallerySection {
  background: var(--vt-surface);
}

.containerFluid {
  width: 100%;
  padding: 0;
}

.galleryRow {
  display: flex;
  flex-wrap: nowrap;
}

.galleryCol {
  flex: 1 1 50%;
}

.galleryImage {
  width: 100%;
  height: auto;
  display: block;
}

.timelineSection {
  background: var(--vt-surface-2);
}

.sectionTitle {
  text-align: center;
  color: var(--vt-ink);
  margin-bottom: 3rem;
  font-size: 36px;
}

.timeline {
  position: relative;
  max-width: 800px;
  margin: 0 auto;
}

.timeline::before {
  content: "";
  position: absolute;
  top: 40px;
  bottom: 0;
  left: 50%;
  width: 0;
  border-left: 1px solid var(--vt-line);
  transform: translateX(-50%);
}

.timelineNode {
  display: flex;
  align-items: flex-start;
  margin-bottom: 2rem;
  position: relative;
}

.timelineNode:nth-child(odd) .timelineContent {
  order: 3;
  margin-left: 1rem;
}

.timelineNode:nth-child(odd) .timelineIcon {
  order: 2;
}

.timelineNode:nth-child(odd) .timelineDate {
  order: 1;
  margin-right: 1rem;
  text-align: right;
}

.timelineNode:nth-child(even) .timelineContent {
  order: 1;
  margin-right: 1rem;
}

.timelineNode:nth-child(even) .timelineIcon {
  order: 2;
}

.timelineNode:nth-child(even) .timelineDate {
  order: 3;
  margin-left: 1rem;
  text-align: left;
}

.timelineContent {
  flex: 0 0 calc(50% - 60px);
  background: var(--vt-surface);
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
  border-radius: 0.25rem;
  box-sizing: border-box;
}

.timelineTitle {
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  padding: 10px 30px;
  border-radius: 0.25rem 0.25rem 0 0;
  margin: 0;
  position: relative;
  font-size: 1.25rem;
}

.timelineContent p {
  padding: 10px 30px;
  color: var(--vt-ink-soft);
  margin: 0;
}

.timelineTitle::after {
  content: "";
  position: absolute;
  top: 50%;
  border: 10px solid transparent;
}

.timelineNode:nth-child(odd) .timelineTitle::after {
  left: 100%;
  border-left-color: var(--vt-surface-deep);
}

.timelineNode:nth-child(even) .timelineTitle::after {
  right: 100%;
  border-right-color: var(--vt-surface-deep);
}

.timelineIcon {
  flex: 0 0 80px;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  z-index: 10;
}

.timelineIconInner {
  width: 80px;
  height: 80px;
  background: var(--vt-surface);
  border-radius: 50%;
  box-shadow: 0 1rem 3rem rgba(0, 0, 0, 0.175);
  display: flex;
  justify-content: center;
  align-items: center;
  font-size: 32px;
  color: var(--vt-accent-ink);
}

.timelineIconInner::after {
  content: "";
  width: 16px;
  height: 16px;
  background: var(--vt-accent-ink);
  border-radius: 50%;
}

.timelineDate {
  flex: 0 0 calc(50% - 60px);
  color: var(--vt-ink-soft);
  font-weight: 600;
  padding-top: 1.5rem;
  box-sizing: border-box;
}

.siteFooter {
  background: var(--vt-surface-2);
  padding-top: 7rem;
  padding-bottom: 7rem;
}

.footerRow {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 2rem;
}

.footerCol {
  flex: 1;
  min-width: 200px;
  box-sizing: border-box;
}

.footerTitle {
  color: var(--vt-ink);
  margin-bottom: 1.5rem;
  font-size: 1.25rem;
}

.footerHours {
  color: var(--vt-ink-soft);
}

.clinicInfo {
  max-width: 100%;
  overflow: hidden;
}

.copyrightCol {
  flex: 0 0 100%;
  margin-top: 2rem;
}

.copyright {
  font-size: 16px;
  color: var(--vt-ink-soft);
}

@media (max-width: 991px) {
  .root {
    padding-top: 74px;
  }

  .navIn {
    height: 74px;
    padding: 0 1rem;
  }

  .heroTitle {
    font-size: 38px;
  }

  .sectionPadding {
    padding-top: 5rem;
    padding-bottom: 5rem;
  }

  .aboutTitle,
  .sectionTitle {
    font-size: 32px;
  }

  .heroImageWrap {
    height: inherit;
  }

  .heroText {
    position: relative;
    bottom: 100px;
    left: 0;
    width: auto;
    margin-bottom: -100px;
    padding: 2rem;
  }

  .animatedInfo {
    min-width: 150px;
  }

  .timelineNode {
    flex-direction: column;
    align-items: flex-start;
  }

  .timeline::before {
    left: 33px;
    top: 60px;
    transform: none;
  }

  .timelineNode:nth-child(odd) .timelineContent,
  .timelineNode:nth-child(even) .timelineContent {
    order: 3;
    margin: 0;
    width: 100%;
    flex: 1 1 100%;
  }

  .timelineNode:nth-child(odd) .timelineIcon,
  .timelineNode:nth-child(even) .timelineIcon {
    order: 2;
    margin: 0;
    position: absolute;
    left: -10px;
    top: 60px;
  }

  .timelineNode:nth-child(odd) .timelineDate,
  .timelineNode:nth-child(even) .timelineDate {
    order: 1;
    margin: 0;
    text-align: left;
    width: 100%;
    flex: 1 1 100%;
    padding-top: 0;
    padding-left: 100px;
  }

  .timelineTitle::after {
    display: none;
  }

  .footerRow {
    gap: 1rem;
  }

  .footerCol {
    flex: 1 1 45%;
  }

  .copyrightCol {
    flex: 1 1 100%;
  }
}

@media (max-width: 767px) {
  .heroText {
    padding: 1.5rem;
  }

  .animatedInfo {
    min-width: 125px;
  }

  .galleryRow {
    flex-wrap: wrap;
  }

  .galleryCol {
    flex: 1 1 100%;
  }

  .footerCol {
    flex: 1 1 100%;
  }
}

@media (max-width: 480px) {
  .heroText {
    padding: 1rem;
  }

  .heroLinks .customLink {
    font-size: 12px;
    line-height: 30px;
    margin-right: 12px;
    padding: 0 25px;
  }

  .contactPhone {
    font-size: 12px;
  }
}

@media (max-width: 360px) {
  .timeline::before {
    left: 42px;
  }
}
